type QAThread = (typeof QA_BASE_THREADS)[number];

const QA_OVERFLOW_THREADS: QAThread[] = Array.from({ length: 28 }, (_, index) => {
  const rowNumber = index + 1;
  return {
    account_id: QA_ACCOUNT.id,
    account_color: QA_ACCOUNT.color,
    account_name: QA_ACCOUNT.display_name,
    thread_id: `qa-overflow-${rowNumber}`,
    from_name: rowNumber % 3 === 0 ? "App QA" : "Workspace Digest",
    subject: `Primary overflow smoke row ${rowNumber}`,
    snippet:
      "Deterministic inbox volume row used to prove scroll reset, pagination, and density behavior.",
    unread: rowNumber % 4 === 0,
    starred: rowNumber === 5,
    last_message_at: NOW - 1000 * 60 * (90 + rowNumber),
    labels: rowNumber === 5 ? ["INBOX", "STARRED"] : ["INBOX"],
    has_attachments: false,
    attachment_names: [],
    important: false,
    message_count: 1,
    participants: [rowNumber % 3 === 0 ? "App QA" : "Workspace Digest"],
  };
});

export const QA_THREADS = [...QA_BASE_THREADS, ...QA_OVERFLOW_THREADS];

